    });

    const inputWrap = document.createElement('div');
    Object.assign(inputWrap.style, { position: 'relative', flex: '1' });

    const input = document.createElement('input');
    input.type = 'text';
    input.placeholder = placeholder;
    Object.assign(input.style, {
