      targetX: null,
      targetY: null,
      targetItemId: 0,
      stateEnteredTurn: world.step,
      lastPlayerX: playerPos?.x ?? null,
      lastPlayerY: playerPos?.y ?? null,
      commandCooldown: 0,
    });
    ps = world.get(entityId, PetState);
  }
  return ps;
}

